package com.shale.ui.controller;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;
final class SettingsUserManagementSemanticRuntimeTest{@Test void launcherPaneAndLifecycleAreFeatureOwned()throws Exception{String launcher=Files.readString(Path.of("src/main/java/com/shale/ui/controller/UserManagementLauncher.java"));String pane=Files.readString(Path.of("src/main/java/com/shale/ui/controller/UserManagementPane.java"));assertTrue(launcher.contains("new DefinitionManagementSession()"));assertTrue(launcher.contains("pane.open()"));assertTrue(pane.contains("CommittedChangeTracker"));assertTrue(pane.contains("disposed.get()"));assertFalse(pane.contains(".shutdown"));}}
